@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  /* The bare trigger, its own <button> (the part adds nz-hit-target only then): at least 24 x 24 px,
     the WCAG 2.2 2.5.8 minimum (M27), as Dialog's and Tooltip's. A composed Button or IconButton
     carries nz-hit-target itself and is at least 32 px already; a consumer's own element through
     `render` keeps its size. */
  .nz-popover-trigger.nz-hit-target {
    min-inline-size: 1.5rem;
    min-block-size: 1.5rem;
  }

  /* one overlay band, ordered by DOM (§12.1 L1). "Overlays enter on spring, exit in 140 ms
     ease-in" (01): scale 0.96 → 1 from the trigger on the spring pair, the opacity on the spring's
     duration (120 ms when reduced, so the fade survives and the scale does not travel). The popup
     scrolls; overlays opened inside it portal next to it, never into it (§12.1 L2). */
  .nz-popover-popup {
    z-index: var(--nz-z-overlay);
    /* the widths include the border, with or without a page reset (§8.1) */
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    inline-size: var(--nz-popover-width, max-content);
    max-inline-size: min(22.5rem, 100vw - 2 * var(--nz-space-4));
    max-block-size: var(--nz-available-height);
    overflow: auto;
    border: var(--nz-border-width-default) solid var(--nz-popover-border, var(--nz-border-subtle));
    border-radius: var(--nz-popover-radius, var(--nz-radius-lg));
    background: var(--nz-popover-bg, var(--nz-bg-surface-raised));
    box-shadow: var(--nz-popover-shadow, var(--nz-elevation-3));
    color: var(--nz-text-primary);
    font: var(--nz-font-body-m);
    letter-spacing: var(--nz-tracking-body-m);
    transform-origin: var(--nz-transform-origin);
    transition:
      scale var(--nz-duration-spring) var(--nz-easing-spring),
      opacity var(--nz-duration-spring) var(--nz-easing-enter);

    &[data-entering] {
      opacity: 0;
      scale: var(--nz-scale-enter);
    }

    &[data-exiting] {
      opacity: 0;
      transition: opacity var(--nz-duration-fade) var(--nz-easing-exit);
    }
  }

  /* the role="dialog" element: the popup's padding, title, text and controls */
  .nz-popover-content {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-2);
    padding: var(--nz-space-4);

    /* Focus lands on this element when nothing inside takes it: it is the container, so it shows
       no ring of its own, as the Dialog's content does not. */
    &:focus-visible {
      outline: none;
    }
  }

  .nz-popover-title {
    margin: 0;
    color: var(--nz-text-primary);
    font: var(--nz-font-heading-h4);
    letter-spacing: var(--nz-tracking-heading-h4);
  }

  .nz-popover-description {
    margin: 0;
    color: var(--nz-text-secondary);
    font: var(--nz-font-body-m);
    letter-spacing: var(--nz-tracking-body-m);
  }

  /* The default Popover.Close, a 32 px IconButton, as a direct child of the popup's content: in the
     top end corner, 8 px in, as the Dialog's sits in its corner. The title leaves room for it. */
  .nz-popover-content > .nz-popover-close.nz-icon-button {
    --_nz-icon-button-fg: var(--nz-icon-secondary);

    position: absolute;
    inset-block-start: var(--nz-space-2);
    inset-inline-end: var(--nz-space-2);
  }

  .nz-popover-content:has(> .nz-popover-close.nz-icon-button) > .nz-popover-title {
    padding-inline-end: var(--nz-space-6);
  }

  @media (forced-colors: active) {
    .nz-popover-popup {
      border-color: CanvasText;
    }
  }
}
